+import { readdirSync, readFileSync } from "node:fs";
+import { join, relative } from "node:path";
+
+import { describe, expect, it } from "vitest";
+
+/**
+ * profile-todo-cleanup — the stale "add an organization parameter" TODO on
+ * `getProfileData` is gone, and its doc comment states the real rule: the
+ * profile is per person, not per workspace. This file lives outside
+ * `features/profile/` on purpose, so its own literals are never scanned.
+ */
+
+function listFiles(dir: string): string[] {
+  const files: string[] = [];
+  for (const entry of readdirSync(dir, { withFileTypes: true })) {
+    const path = join(dir, entry.name);
+    if (entry.isDirectory()) files.push(...listFiles(path));
+    else if (entry.isFile()) files.push(path);
+  }
+  return files;
+}
+
+describe("profile-todo-cleanup doc comment", () => {
+  it("AC-1: no file under features/profile/ mentions multi-workspace support or pairs TODO with organizationId", () => {
+    const root = process.cwd();
+    const profileDir = join(root, "features", "profile");
+    const files = listFiles(profileDir);
+    expect(files.length).toBeGreaterThan(0);
+
+    const hits: string[] = [];
+    for (const file of files) {
+      const text = readFileSync(file, "utf8");
+      if (text.includes("multi-workspace support")) {
+        hits.push(`${relative(root, file)} multi-workspace support`);
+      }
+      text.split("\n").forEach((line, index) => {
+        if (line.includes("TODO") && line.includes("organizationId")) {
+          hits.push(
+            `${relative(root, file)}:${index + 1} TODO + organizationId`,
+          );
+        }
+      });
+    }
+
+    expect(hits).toEqual([]);
+  });
+
+  it("AC-2: the doc comment directly above getProfileData says the profile is per person, not per workspace, with no organization id", () => {
+    const text = readFileSync(
+      join(process.cwd(), "features", "profile", "services", "get-profile.ts"),
+      "utf8",
+    );
+    const marker = "export async function getProfileData";
+    const exportIndex = text.indexOf(marker);
+    expect(exportIndex).toBeGreaterThan(-1);
+
+    const before = text.slice(0, exportIndex).trimEnd();
+    expect(before.endsWith("*/")).toBe(true);
+    const start = before.lastIndexOf("/**");
+    expect(start).toBeGreaterThan(-1);
+
+    const comment = before.slice(start).toLowerCase();
+    expect(comment).toContain("per person");
+    expect(comment).toContain("not per workspace");
+    expect(comment).toContain("no organization id");
+  });
+});
